def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    divisors = []
    limit = int(math.isqrt(n))

    for i in range(1, limit + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)

    divisors.sort()

    if k <= len(divisors):
        print(divisors[k - 1])
    else:
        print(-1)

if __name__ == "__main__":
    solve()

